package com.adsamcik.tracker.tracker.component.producerimport android.content.Contextimport android.content.ContextWrapperimport android.telephony.CellInfoLteimport android.telephony.CellIdentityLteimport android.telephony.CellSignalStrengthLteimport android.telephony.SubscriptionManagerimport android.telephony.TelephonyManagerimport com.adsamcik.tracker.shared.base.assist.Assistimport com.adsamcik.tracker.tracker.component.TrackerDataProducerObserverimport com.adsamcik.tracker.tracker.data.collection.MutableCollectionTempDataimport io.kotest.matchers.nulls.shouldBeNullimport io.kotest.matchers.nulls.shouldNotBeNullimport io.mockk.everyimport io.mockk.mockkimport io.mockk.mockkObjectimport io.mockk.unmockkAllimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.ExperimentalCoroutinesApiimport kotlinx.coroutines.test.UnconfinedTestDispatcherimport kotlinx.coroutines.test.resetMainimport kotlinx.coroutines.test.setMainimport org.junit.jupiter.api.AfterEachimport org.junit.jupiter.api.BeforeEachimport org.junit.jupiter.api.DisplayNameimport org.junit.jupiter.api.Nestedimport org.junit.jupiter.api.Test@DisplayName("CellDataProducer")@OptIn(ExperimentalCoroutinesApi::class)class CellDataProducerTest {	private lateinit var observer: TrackerDataProducerObserver	private lateinit var producer: CellDataProducer	private lateinit var mockContext: Context	private lateinit var mockTelephonyManager: TelephonyManager	private lateinit var mockSubscriptionManager: SubscriptionManager	@BeforeEach	fun setUp() {		Dispatchers.setMain(UnconfinedTestDispatcher())		observer = mockk(relaxed = true)		producer = CellDataProducer(observer)		mockContext = mockk<ContextWrapper>(relaxed = true)		mockTelephonyManager = mockk(relaxed = true)		mockSubscriptionManager = mockk(relaxed = true)		// Inject fields via reflection since onEnable requires full Android context		setPrivateField("context", mockContext)		setPrivateField("telephonyManager", mockTelephonyManager)		setPrivateField("subscriptionManager", mockSubscriptionManager)		// With isReturnDefaultValues the default permission check returns GRANTED,		// so the code enters the subscriptionManager path. Ensure the relaxed mock		// returns null (matching real behaviour when there are no active subs) so		// the producer falls back to the single-arg getScanData.		every { mockSubscriptionManager.activeSubscriptionInfoList } returns null	}	@AfterEach	fun tearDown() {		unmockkAll()		Dispatchers.resetMain()	}	private fun setPrivateField(name: String, value: Any?) {		val field = CellDataProducer::class.java.getDeclaredField(name)		field.isAccessible = true		field.set(producer, value)	}	private fun getPrivateField(name: String): Any? {		val field = CellDataProducer::class.java.getDeclaredField(name)		field.isAccessible = true		return field.get(producer)	}	private fun createTempData(): MutableCollectionTempData {		return MutableCollectionTempData(System.currentTimeMillis(), System.nanoTime())	}	private fun mockAirplaneMode(enabled: Boolean) {		mockkObject(Assist)		every { Assist.isAirplaneModeEnabled(any()) } returns enabled	}	@Nested	@DisplayName("onDataRequest")	inner class OnDataRequest {		@Test		fun `clears cached data and returns nothing in airplane mode`() {			mockAirplaneMode(enabled = true)			val tempData = createTempData()			producer.onDataRequest(tempData)			getPrivateField("lastCellScanData").shouldBeNull()			tempData.tryGet<Any>("CELL").shouldBeNull()		}		@Test		fun `returns null when network operator is empty`() {			mockAirplaneMode(enabled = false)			every { mockTelephonyManager.networkOperator } returns ""			val tempData = createTempData()			producer.onDataRequest(tempData)			tempData.tryGet<Any>("CELL").shouldBeNull()		}		@Test		fun `returns null when allCellInfo is null`() {			mockAirplaneMode(enabled = false)			every { mockTelephonyManager.networkOperator } returns "310260"			every { mockTelephonyManager.networkOperatorName } returns "T-Mobile"			every { mockTelephonyManager.allCellInfo } returns null			val tempData = createTempData()			producer.onDataRequest(tempData)			tempData.tryGet<Any>("CELL").shouldBeNull()		}		@Test		fun `produces cell data when cell info is available`() {			mockAirplaneMode(enabled = false)			every { mockTelephonyManager.networkOperator } returns "310260"			every { mockTelephonyManager.networkOperatorName } returns "T-Mobile"			val mockCellInfoLte = mockk<CellInfoLte>(relaxed = true)			every { mockCellInfoLte.isRegistered } returns true			val mockCellIdentity = mockk<CellIdentityLte>(relaxed = true)			every { mockCellIdentity.mccString } returns "310"			every { mockCellIdentity.mncString } returns "260"			every { mockCellInfoLte.cellIdentity } returns mockCellIdentity			every { mockCellInfoLte.cellSignalStrength } returns mockk<CellSignalStrengthLte>(relaxed = true)			every { mockTelephonyManager.allCellInfo } returns listOf(mockCellInfoLte)			val tempData = createTempData()			producer.onDataRequest(tempData)			tempData.tryGet<Any>("CELL").shouldNotBeNull()		}	}	@Nested	@DisplayName("onDisable")	inner class OnDisable {		@Test		fun `clears all state on disable`() {			// Set canBeEnabled and isEnabled so onDisable doesn't assert			producer.canBeEnabled = true			val isEnabledField = producer.javaClass.superclass.getDeclaredField("isEnabled")			isEnabledField.isAccessible = true			isEnabledField.set(producer, true)			producer.onDisable(mockContext)			getPrivateField("context").shouldBeNull()			getPrivateField("telephonyManager").shouldBeNull()			getPrivateField("subscriptionManager").shouldBeNull()			getPrivateField("lastCellScanData").shouldBeNull()		}	}	@Nested	@DisplayName("cache behavior")	inner class CacheBehavior {		@Test		fun `uses cached data within TTL window`() {			mockAirplaneMode(enabled = false)			every { mockTelephonyManager.networkOperator } returns "310260"			every { mockTelephonyManager.networkOperatorName } returns "T-Mobile"			val mockCellInfoLte = mockk<CellInfoLte>(relaxed = true)			every { mockCellInfoLte.isRegistered } returns true			val mockCellIdentity = mockk<CellIdentityLte>(relaxed = true)			every { mockCellIdentity.mccString } returns "310"			every { mockCellIdentity.mncString } returns "260"			every { mockCellInfoLte.cellIdentity } returns mockCellIdentity			every { mockCellInfoLte.cellSignalStrength } returns mockk<CellSignalStrengthLte>(relaxed = true)			every { mockTelephonyManager.allCellInfo } returns listOf(mockCellInfoLte)			// First request populates cache			val tempData1 = createTempData()			producer.onDataRequest(tempData1)			tempData1.tryGet<Any>("CELL").shouldNotBeNull()			// Immediately return empty allCellInfo to prove cache is used			every { mockTelephonyManager.allCellInfo } returns null			// Second request should use cached data (within TTL)			val tempData2 = createTempData()			producer.onDataRequest(tempData2)			tempData2.tryGet<Any>("CELL").shouldNotBeNull()		}	}}